        if "imap" in self.services:
            return True
        return False

    def canProviderPOP3(self):
        if "pop3" in self.services:
            return True
        return False

    def getDisplayName(self):
        displayName = self.dom.findall('emailProvider/displayName')
        if len(displayName) > 0:
