class bitarray():
    def __init__(self,length,defaultValue=False):
        if (length < 0):
            raise Exception("Length param error")
        self.array=[]
        self.length=length
        fillValue=defaultValue
        for  i in range(self.length):
            self.array.append(defaultValue)
        self.version=0

    def input_from_array(self,value):
        if(isinstance(value,list)==False):
            raise Exception("value is not a Array")
        if (value is None or len(value)!=self.length):
            raise Exception("ArgumentException if value == null or value.Length != this.Length.")
        for i in range(self.length):
            self.Set(i,value[i])
        self.version+=1
        return self

    def __len__(self):
        return self.length

    def __str__(self):
        str="["
        for i in range(self.length):
            str+="1" if self.array[i]==True else "0"
            str+=" "
        str+="]"
        return str

    def Get (self,index):
        if (index < 0 or index >=self.length):
            raise Exception("ArgumentOutOfRangeException if index < 0 or index >= GetLength()")
        return self.array[index]

    def Set (self,index,value):
        if (index < 0 or index >=self.length):
            raise Exception("ArgumentOutOfRangeException if index < 0 or index >= GetLength()")
        if (value):
            self.array[index]=True
        else:
            self.array[index]=False
        self.version+=1

    def SetAll(self,value):
        for  i in range(self.length):
            self.Set(i,value)
        self.version+=1

    def And (self,value):
        if(isinstance(value,BitArray)==False):
            raise Exception("value is not a BitArray")
        if (value is None or len(value)!=self.length):
            raise Exception("ArgumentException if value == null or value.Length != this.Length.")
        for i in range(self.length):
            self.array[i]&=value.Get(i)
        self.version+=1
        return self

    def Or (self,value):
        if(isinstance(value,BitArray)==False):
            raise Exception("value is not a BitArray")
        if (value is None or len(value)!=self.length):
            raise Exception("ArgumentException if value == null or value.Length != this.Length.")
        for i in range(self.length):
            self.array[i]|=value.Get(i)
        self.version+=1
        return self

    def Xor (self,value):
        if(isinstance(value,BitArray)==False):
            raise Exception("value is not a BitArray")
        if (value is None or len(value)!=self.length):
            raise Exception("ArgumentException if value == null or value.Length != this.Length.")
        for i in range(self.length):
            self.array[i]^=value.Get(i)
        self.version+=1
        return self

    def Not (self):
        for i in range(self.length):
            self.array[i] =not self.array[i]
        self.version+=1
        return self

'''
Given two words (beginWord and endWord), and a dictionary's word list, find all shortest transformation sequence(s) from beginWord to endWord, such that:

Only one letter can be changed at a time
Each intermediate word must exist in the word list
For example,

Given:
beginWord = "hit"
endWord = "cog"
wordList = ["hot","dot","dog","lot","log"]
Return
  [
    ["hit","hot","dot","dog","cog"],
    ["hit","hot","lot","log","cog"]
  ]
Note:
All words have the same length.
All words contain only lowercase alphabetic characters.
'''

class Solution(object):
    def findLadders(self, beginWord, endWord, wordlist):
        """
        :type beginWord: str
        :type endWord: str
        :type wordlist: Set[str]
        :rtype: List[List[int]]
        """

        def bfs(front_level, end_level, is_forward, word_set, path_dic):
            if len(front_level) == 0:
                return False
            if len(front_level) > len(end_level):
                return bfs(end_level, front_level, not is_forward, word_set, path_dic)
            for word in (front_level | end_level):
                word_set.discard(word)
            next_level = set()
            done = False
            while front_level:
                word = front_level.pop()
                for c in 'abcdefghijklmnopqrstuvwxyz':
                    for i in range(len(word)):
                        new_word = word[:i] + c + word[i + 1:]
                        if new_word in end_level:
                            done = True
                            add_path(word, new_word, is_forward, path_dic)
                        else:
                            if new_word in word_set:
                                next_level.add(new_word)
                                add_path(word, new_word, is_forward, path_dic)
            return done or bfs(next_level, end_level, is_forward, word_set, path_dic)

        def add_path(word, new_word, is_forward, path_dic):
            if is_forward:
                path_dic[word] = path_dic.get(word, []) + [new_word]
            else:
                path_dic[new_word] = path_dic.get(new_word, []) + [word]

        def construct_path(word, end_word, path_dic, path, paths):
            if word == end_word:
                paths.append(path)
                return
            if word in path_dic:
                for item in path_dic[word]:
                    construct_path(item, end_word, path_dic, path + [item], paths)

        front_level, end_level = {beginWord}, {endWord}
        path_dic = {}
        bfs(front_level, end_level, True, wordlist, path_dic)
        path, paths = [beginWord], []
        construct_path(beginWord, endWord, path_dic, path, paths)
        return paths


if __name__ == "__main__":
    assert Solution().findLadders("hit", "cog", {"hot", "dot", "dog", "lot", "log"}) == [
        ["hit", "hot", "dot", "dog", "cog"],
        ["hit", "hot", "lot", "log", "cog"]
    ]

